From 3335dccdc76066c0284c1ebb5e2676e8f1925fca Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:54:21 +0100
Subject: [PATCH] applets/lock_logout: offer to run actions after a delay

Shutting down or sleeping after a delay needed a terminal or the Timer
widget. Right-clicking a button now offers to run it after 15 minutes to
2 hours, and a badge, the tooltip and a Cancel entry show the schedule.

BUG: 369845
---
 applets/lock_logout/data.js  |   8 +++
 applets/lock_logout/main.qml | 108 +++++++++++++++++++++++++++++++++--
 2 files changed, 111 insertions(+), 5 deletions(-)

diff --git a/applets/lock_logout/data.js b/applets/lock_logout/data.js
index 12424cf4b3..15664af1d9 100644
--- a/applets/lock_logout/data.js
+++ b/applets/lock_logout/data.js
@@ -4,6 +4,7 @@ var data = [{
     configKey: "lockScreen",
     tooltip_mainText: i18n("Lock"),
     tooltip_subText: i18n("Lock the screen"),
+    scheduleText: "",
     requires: "Lock"
 }, {
     icon: "system-switch-user",
@@ -11,6 +12,7 @@ var data = [{
     configKey: "switchUser",
     tooltip_mainText: i18n("Switch user…"),
     tooltip_subText: i18n("Start a parallel session as a different user"),
+    scheduleText: "",
     requires: ""
 }, {
     icon: "system-shutdown",
@@ -18,6 +20,7 @@ var data = [{
     configKey: "requestShutDown",
     tooltip_mainText: i18n("Shut down"),
     tooltip_subText: i18n("Turn off the computer"),
+    scheduleText: i18nc("@action:inmenu", "Shut Down"),
     requires: "Shutdown"
 }, {
     icon: "system-reboot",
@@ -25,6 +28,7 @@ var data = [{
     configKey: "requestReboot",
     tooltip_mainText: i18n("Restart"),
     tooltip_subText: i18n("Reboot the computer"),
+    scheduleText: i18nc("@action:inmenu", "Restart"),
     requires: "Reboot"
 }, {
     icon: "system-log-out",
@@ -32,6 +36,7 @@ var data = [{
     configKey: "requestLogout",
     tooltip_mainText: i18n("Log out"),
     tooltip_subText: i18n("End the session"),
+    scheduleText: i18nc("@action:inmenu", "Log Out"),
     requires: "Logout"
 }, {
     icon: "system-log-out",
@@ -39,6 +44,7 @@ var data = [{
     configKey: "requestLogoutScreen",
     tooltip_mainText: i18nc("@info:tooltip", "Show logout screen"),
     tooltip_subText: i18n("Log out, turn off, or restart the computer"),
+    scheduleText: "",
     requires: "Logout"
 }, {
     icon: "system-suspend",
@@ -46,6 +52,7 @@ var data = [{
     configKey: "suspendToRam",
     tooltip_mainText: i18nc("Suspend to RAM", "Sleep"),
     tooltip_subText: i18n("Sleep (suspend to RAM)"),
+    scheduleText: i18nc("@action:inmenu Suspend to RAM", "Sleep"),
     requires: "Suspend"
 }, {
     icon: "system-suspend-hibernate",
@@ -53,5 +60,6 @@ var data = [{
     configKey: "suspendToDisk",
     tooltip_mainText: i18n("Hibernate"),
     tooltip_subText: i18n("Hibernate (suspend to disk)"),
+    scheduleText: i18nc("@action:inmenu", "Hibernate"),
     requires: "Hibernate"
 }]
diff --git a/applets/lock_logout/main.qml b/applets/lock_logout/main.qml
index d89b3a0b43..da90b764e0 100644
--- a/applets/lock_logout/main.qml
+++ b/applets/lock_logout/main.qml
@@ -20,6 +20,87 @@ PlasmoidItem {
     readonly property int minButtonSize: Kirigami.Units.iconSizes.small
     property bool initialized: false

+    property var hoveredAction: null
+    property var scheduledAction: null
+    property double scheduledTime: 0
+    readonly property string scheduledTimeText: Qt.formatTime(new Date(scheduledTime), Qt.locale().timeFormat(Locale.ShortFormat))
+
+    readonly property bool canScheduleHovered: hoveredAction !== null && hoveredAction.scheduleText !== ""
+
+    function scheduleActionText(minutes) {
+        if (!canScheduleHovered) {
+            return "";
+        }
+        const duration = minutes < 60
+            ? i18ncp("@item:inmenu", "%1 Minute", "%1 Minutes", minutes)
+            : i18ncp("@item:inmenu", "%1 Hour", "%1 Hours", minutes / 60);
+        return i18nc("@action:inmenu %1 is an action such as Shut Down, %2 is a duration such as 15 Minutes", "%1 in %2", hoveredAction.scheduleText, duration);
+    }
+
+    function scheduleHovered(minutes) {
+        scheduledTime = Date.now() + minutes * 60000;
+        scheduledAction = hoveredAction;
+    }
+
+    Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            visible: root.canScheduleHovered
+            text: root.scheduleActionText(15)
+            icon.name: "chronometer"
+            onTriggered: root.scheduleHovered(15)
+        },
+        PlasmaCore.Action {
+            visible: root.canScheduleHovered
+            text: root.scheduleActionText(30)
+            icon.name: "chronometer"
+            onTriggered: root.scheduleHovered(30)
+        },
+        PlasmaCore.Action {
+            visible: root.canScheduleHovered
+            text: root.scheduleActionText(60)
+            icon.name: "chronometer"
+            onTriggered: root.scheduleHovered(60)
+        },
+        PlasmaCore.Action {
+            visible: root.canScheduleHovered
+            text: root.scheduleActionText(120)
+            icon.name: "chronometer"
+            onTriggered: root.scheduleHovered(120)
+        },
+        PlasmaCore.Action {
+            visible: root.scheduledAction !== null
+            text: visible ? i18nc("@action:inmenu %1 is an action such as Shut Down, %2 is a time", "Cancel %1 at %2", root.scheduledAction.scheduleText, root.scheduledTimeText) : ""
+            icon.name: "dialog-cancel"
+            onTriggered: root.scheduledAction = null
+        },
+        PlasmaCore.Action {
+            isSeparator: true
+            visible: root.canScheduleHovered || root.scheduledAction !== null
+        }
+    ]
+
+    KWorkspace.SessionManagement {
+        id: session
+    }
+
+    Timer {
+        running: root.scheduledAction !== null
+        interval: 1000
+        repeat: true
+        onTriggered: {
+            const late = Date.now() - root.scheduledTime;
+            if (late < 0) {
+                return;
+            }
+            const operation = root.scheduledAction.operation;
+            root.scheduledAction = null;
+            // Don't act on a time that passed while the computer was asleep
+            if (late < 60000) {
+                session[operation]();
+            }
+        }
+    }
+
     preferredRepresentation: fullRepresentation
     fullRepresentation: Flow {
         id: lockout
@@ -66,10 +147,6 @@ PlasmoidItem {
             }
         }

-        KWorkspace.SessionManagement {
-            id: session
-        }
-
         function buildOrderedModel() {
             orderedActionsModel.clear();

@@ -133,15 +210,18 @@ PlasmoidItem {
                 required property string tooltip_mainText
                 required property string tooltip_subText
                 required property string operation
+                required property string scheduleText
                 required property var model // used to access icon because ToopTipArea already has icon property

+                readonly property bool scheduled: root.scheduledAction !== null && root.scheduledAction.operation === operation
+
                 visible: Plasmoid.configuration["show_" + configKey] && (requires !== ""|| session["can" + requires])
                 width: items.itemWidth
                 height: items.itemHeight

                 activeFocusOnTab: true
                 mainText: tooltip_mainText
-                subText: tooltip_subText
+                subText: scheduled ? i18nc("@info:tooltip %1 is a time", "Scheduled for %1", root.scheduledTimeText) : tooltip_subText
                 textFormat: Text.PlainText

                 Accessible.name: iconDelegate.mainText
@@ -158,6 +238,15 @@ PlasmoidItem {
                     }
                 }

+                onContainsMouseChanged: {
+                    if (containsMouse) {
+                        root.hoveredAction = {
+                            operation: operation,
+                            scheduleText: scheduleText,
+                        };
+                    }
+                }
+
                 TapHandler {
                     id: tapHandler
                     onTapped: lockout.performOperation(iconDelegate.operation)
@@ -172,6 +261,15 @@ PlasmoidItem {
                     scale: tapHandler.pressed ? 0.9 : 1
                     active: iconDelegate.containsMouse
                 }
+
+                Kirigami.Icon {
+                    anchors.right: iconButton.right
+                    anchors.bottom: iconButton.bottom
+                    width: Math.round(iconButton.width / 2)
+                    height: width
+                    source: "chronometer"
+                    visible: iconDelegate.scheduled
+                }
             }
         }

-- 
2.53.0
